"""`KK Hair`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = 'KK Hair'


def build(lib):
    t = lib.new_material(NAME, props={
            'use_backface_culling_lightprobe_volume': False,
            'preview_render_type': 'FLAT',
            'diffuse_color': (0.48582926, 0.45060727, 0.33487773, 1.0),
            'roughness': 1.0,
            'line_color': (0.0, 0.0, 0.0, 1.0),
        })

    t.node('NodeFrame', 'FrameInfo.002', props={
        'location': (-368.33334, 113.63333),
        'width': 1133.0724,
        'height': 451.3,
        'label': 'Shader',
        'use_custom_color': True,
        'color': (0.33001542, 0.4420454, 0.6247832),
        'label_size': 23,
    })
    t.node('NodeFrame', 'FrameInfo.001', props={
        'location': (-656.3333, 112.299995),
        'width': 247.50919,
        'height': 269.3,
        'label': 'Texture files',
        'use_custom_color': True,
        'color': (0.2901505, 0.6787529, 0.1812863),
        'label_size': 23,
    })
    t.node('NodeFrame', 'FrameInfo.003', props={
        'location': (782.3333, 112.96667),
        'width': 198.0,
        'height': 142.63333,
        'label': 'Output',
        'use_custom_color': True,
        'color': (0.6247832, 0.073067226, 0.042191483),
        'label_size': 23,
    })
    t.node('ShaderNodeGroup', 'combine', parent='FrameInfo.002', inputs={'Alpha mask (custom)': (1.0, 1.0, 1.0, 1.0), 'Force visibility': 0.0}, hide_inputs=('Alpha mask (custom)', 'Force visibility', 'Force custom mask'), props={
        'node_tree': lib.group('.Combine colors'),
        'location': (876.78674, -40.289642),
        'width': 227.07237,
    })
    t.node('ShaderNodeGroup', 'dark', parent='FrameInfo.002', inputs={'Override detail color?': 0.0, 'Detail intensity': 0.8, 'Highlight color': (1.0, 1.0, 1.0, 1.0), 'Use color mask?': 0.0, 'Color mask intensity (root)': 1.0, 'Color mask intensity (tip)': 1.0}, props={
        'node_tree': lib.group('.KK Hair'),
        'location': (451.742, -40.402954),
        'width': 400.0,
    })
    t.node('ShaderNodeGroup', 'light', parent='FrameInfo.002', inputs={'Override detail color?': 0.0, 'Detail intensity': 0.8, 'Highlight color': (1.0, 1.0, 1.0, 1.0), 'Use color mask?': 0.0, 'Color mask intensity (root)': 1.0, 'Color mask intensity (tip)': 1.0}, props={
        'node_tree': lib.group('.KK Hair'),
        'location': (28.708527, -40.402954),
        'width': 400.0,
    })
    t.node('ShaderNodeOutputMaterial', 'out', parent='FrameInfo.003', hide_inputs=('Volume', 'Displacement', 'Thickness'), props={
        'location': (29.152649, -40.114372),
    })
    t.node('ShaderNodeGroup', 'textures', parent='FrameInfo.001', hide_outputs=('Main texture (alpha)', 'Main texture (plain)', 'Color mask (plain)', 'Pattern (base)', 'Pattern (red)', 'Pattern (green)', 'Pattern (blue)', 'Alpha mask', 'Alpha mask (alpha)', 'Normal passthrough'), props={
        'node_tree': lib.group('.Tex General'),
        'location': (29.32013, -40.187202),
        'width': 189.50919,
    })

    t.link('combine', 'Result', 'out', 'Surface')
    t.link('textures', 'Toon shading', 'combine', 'Toon shading')
    t.link('textures', 'Alpha mask (hair alpha)', 'combine', 'Alpha mask')
    t.link('textures', 'Alpha mask (hair alpha)', 'combine', 'Alpha mask (alpha)')
    t.link('textures', 'Alpha mask (hair alpha)', 'combine', 'Main texture (alpha)')
    t.link('textures', 'Main texture', 'light', 'Main texture')
    t.link('textures', 'Detail mask', 'light', 'Detail mask')
    t.link('textures', 'Hair shine', 'light', 'Hair shine')
    t.link('textures', 'Color mask', 'light', 'Color mask')
    t.link('dark', 'Hair out', 'combine', 'Dark colors')
    t.link('light', 'Hair out', 'combine', 'Light colors')
    t.link('textures', 'Color mask', 'dark', 'Color mask')
    t.link('textures', 'Detail mask', 'dark', 'Detail mask')
    t.link('textures', 'Hair shine', 'dark', 'Hair shine')
    t.link('textures', 'Main texture (dark)', 'dark', 'Main texture')
    return t
